{"action":"write_file","path":"isbn.js","content":"'use strict';

function isValidIsbn10(text) {
  // Check if text is a string; throw TypeError if not
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  // Remove hyphens and spaces
  const cleaned = text.replace(/[-\s]/g, '');

  // Must be exactly 10 characters
  if (cleaned.length !== 10) {
    return false;
  }

  // First 9 characters must be digits
  for (let i = 0; i < 9; i++) {
    const char = cleaned[i];
    if (char < '0' || char > '9') {
      return false;
    }
  }

  // Last character must be a digit or X (uppercase or lowercase)
  const checkChar = cleaned[9];
  if (!((checkChar >= '0' && checkChar <= '9') || checkChar === 'X' || checkChar === 'x')) {
    return false;
  }

  // Calculate weighted sum
  let sum = 0;
  for (let i = 0; i < 9; i++) {
    sum += (cleaned[i] - '0') * (10 - i);
  }

  // Add check character value (X = 10)
  const checkValue = checkChar === 'X' || checkChar === 'x' ? 10 : (checkChar - '0');
  sum += checkValue * 1;

  // Valid if sum is divisible by 11
  return sum % 11 === 0;
}

module.exports = { isValidIsbn10 };
